import React, { useState } from 'react';
import { Collapse, Card, Typography, Button, Tag, Divider, Space, Alert, Modal } from 'antd';
import { 
  QuestionCircleOutlined, 
  DeleteOutlined, 
  WarningOutlined,
  MessageOutlined,
  BulbOutlined,
  SafetyOutlined,
  RobotOutlined,
  BookOutlined,
  ThunderboltOutlined,
  ExclamationCircleOutlined
} from '@ant-design/icons';

const { Panel } = Collapse;
const { Title, Text, Paragraph } = Typography;

interface HelpProps {}

const Help: React.FC<HelpProps> = () => {
  const [isDeletionModalOpen, setIsDeletionModalOpen] = useState(false);

  const handleShowDeletionWarning = () => {
    setIsDeletionModalOpen(true);
  };

  return (
    <div className="help-page" style={{ padding: '20px', maxWidth: '800px', margin: '0 auto' }}>
      {/* Заголовок */}
      <div style={{ textAlign: 'center', marginBottom: '30px' }}>
        <Title level={2}>
          <BookOutlined style={{ marginRight: '10px' }} />
          Инструкция по работе с SoulPulse
        </Title>
        <Text type="secondary">
          Полное руководство по использованию интеллектуального ИИ-ассистента
        </Text>
        
        {/* Краткое описание системы */}
        <Card 
          style={{ 
            marginTop: '20px', 
            marginBottom: '20px',
            background: 'var(--sp-bg-secondary)',
            border: '1px solid var(--sp-border-primary)'
          }}
        >
          <Title level={4}>🤖 Что такое SoulPulse?</Title>
          <Paragraph>
            <strong>SoulPulse</strong> — это продвинутый ИИ-ассистент с персонализированными личностями, 
            работающий через Telegram бот и современное мини-приложение.
          </Paragraph>
          
          <Title level={5}>✨ Ключевые возможности:</Title>
          <ul style={{ marginLeft: '20px', lineHeight: '1.8' }}>
            <li><strong>🧠 10+ ИИ-личностей</strong> — от деловых помощников до творческих партнеров</li>
            <li><strong>💬 Двойной интерфейс</strong> — общение в Telegram + полный функционал в мини-апп</li>
            <li><strong>🗑️ Умное управление историей</strong> — реальное удаление только в мини-приложении</li>
            <li><strong>📊 Продвинутая аналитика</strong> — анализ эмоций, ключевые слова, напоминания</li>
            <li><strong>⚙️ Гибкие настройки</strong> — выбор LLM провайдера, персонализация</li>
            <li><strong>🎨 Современный UI</strong> — темная/светлая тема, адаптация под Telegram</li>
          </ul>
        </Card>
      </div>

      {/* Критическое предупреждение */}
      <Alert
        message="🚨 ВАЖНО: Удаление сообщений работает ТОЛЬКО в мини-приложении!"
        description={
          <div>
            <p><strong>❌ Удаление в Telegram НЕ работает с нашей системой!</strong></p>
            <p>
              ✅ <strong>Для реального удаления используйте ТОЛЬКО мини-приложение!</strong><br/>
              В мини-апп есть кнопка "Очистить историю" — она работает правильно.
            </p>
            <p>
              🔄 Удаление в Telegram боте остается только в интерфейсе, но сообщения сохраняются в базе данных.
            </p>
            <Button 
              type="primary" 
              danger 
              icon={<ExclamationCircleOutlined />}
              onClick={handleShowDeletionWarning}
              style={{ marginTop: '10px' }}
            >
              Подробнее об удалении
            </Button>
          </div>
        }
        type="warning"
        showIcon
        style={{ marginBottom: '30px' }}
      />

      {/* Основные разделы */}
      <Collapse 
        defaultActiveKey={['1']} 
        size="large"
        style={{ marginBottom: '20px' }}
      >
        {/* Общение с ботом */}
        <Panel 
          header={
            <span>
              <MessageOutlined style={{ marginRight: '8px' }} />
              💬 Общение с ботом
            </span>
          } 
          key="1"
        >
          <Card size="small" style={{ marginBottom: '15px' }}>
            <Title level={4}>Как общаться:</Title>
            <Paragraph>
              • Просто напишите сообщение в чат с ботом - он ответит<br/>
              • Поддерживаются разные личности AI<br/>
              • Автоматический анализ эмоций и ключевых слов<br/>
              • Система напоминаний и работа с памятью
            </Paragraph>
          </Card>

          <Card size="small">
            <Title level={4}>Настройки личностей:</Title>
            <Paragraph>
              • Перейдите в раздел "Личности" для выбора AI-помощника<br/>
              • Можно выбрать базовую личность или дополнительную<br/>
              • Каждая личность имеет свои особенности и стиль общения
            </Paragraph>
          </Card>
        </Panel>

        {/* Удаление сообщений */}
        <Panel 
          header={
            <span style={{ color: '#ff4d4f' }}>
              <DeleteOutlined style={{ marginRight: '8px' }} />
              🗑️ Удаление сообщений (ТОЛЬКО в мини-апп!)
            </span>
          } 
          key="2"
        >
          <Alert
            message="❌ Удаление в Telegram боте НЕ работает! ✅ Используйте мини-приложение!"
            type="warning"
            style={{ marginBottom: '15px' }}
          />

          <Card size="small" style={{ marginBottom: '15px' }}>
            <Title level={4}>✅ Правильный способ - в мини-приложении:</Title>
            <Paragraph>
              <Tag color="green">Рекомендуемый способ:</Tag><br/>
              • Откройте мини-приложение (кнопка "Меню")<br/>
              • Перейдите в раздел "Чат в приложении"<br/>
              • Используйте кнопку "🗑️ Очистить историю"<br/>
              • ✅ Это единственный способ реального удаления!
            </Paragraph>
          </Card>

          <Card size="small" style={{ marginBottom: '15px' }}>
            <Title level={4}>❌ Что НЕ работает:</Title>
            <Paragraph>
              <Tag color="red">Не используйте:</Tag><br/>
              • Удаление сообщений в Telegram боте<br/>
              • Команды /delete_last, /clear_chat (устарели)<br/>
              • Долгий тап → Delete в Telegram<br/>
              • ⚠️ Эти способы НЕ удаляют из базы данных!
            </Paragraph>
          </Card>

          <Card size="small">
            <Title level={4}>🔄 Как это работает:</Title>
            <Paragraph>
              • Telegram бот и мини-приложение используют разные механизмы<br/>
              • Только мини-приложение может реально удалять из БД<br/>
              • Удаление в Telegram остается только визуальным<br/>
              • Для полной очистки всегда используйте мини-апп
            </Paragraph>
          </Card>
        </Panel>

        {/* Команды бота */}
        <Panel 
          header={
            <span>
              <RobotOutlined style={{ marginRight: '8px' }} />
              📱 Команды бота
            </span>
          } 
          key="3"
        >
          <Card size="small" style={{ marginBottom: '15px' }}>
            <Title level={4}>Основные команды:</Title>
            <Paragraph>
              • <code>/help</code> или <code>/start</code> - полная справка<br/>
              • <code>/commands</code> - список всех команд
            </Paragraph>
          </Card>

          <Card size="small" style={{ marginBottom: '15px' }}>
            <Title level={4}>Команды удаления:</Title>
            <Paragraph>
              • <code>/delete_last N</code> - удалить последние N сообщений<br/>
              • <code>/confirm_single_delete ID</code> - безопасное удаление одного<br/>
              • <code>/clear_chat</code> - очистить весь чат
            </Paragraph>
          </Card>
        </Panel>

        {/* Безопасность */}
        <Panel 
          header={
            <span>
              <SafetyOutlined style={{ marginRight: '8px' }} />
              🛡️ Безопасность
            </span>
          } 
          key="4"
        >
          <Card size="small" style={{ marginBottom: '15px' }}>
            <Title level={4}>Защита данных:</Title>
            <Paragraph>
              • Можно удалять только свои собственные сообщения<br/>
              • Проверка авторизации для всех операций<br/>
              • Каскадное удаление всех связанных данных<br/>
              • Все операции логируются для безопасности
            </Paragraph>
          </Card>

          <Card size="small">
            <Title level={4}>Меры предосторожности:</Title>
            <Paragraph>
              • Двойное подтверждение для массового удаления<br/>
              • Четкие предупреждения о необратимости<br/>
              • Лимиты на количество удаляемых сообщений<br/>
              • Возможность отмены на любом этапе
            </Paragraph>
          </Card>
        </Panel>

        {/* Настройки и персонализация */}
        <Panel 
          header={
            <span>
              <ThunderboltOutlined style={{ marginRight: '8px' }} />
              ⚙️ Настройки и персонализация
            </span>
          } 
          key="5"
        >
          <Card size="small" style={{ marginBottom: '15px' }}>
            <Title level={4}>LLM настройки:</Title>
            <Paragraph>
              • Выбор провайдера LLM (DeepSeek, OpenAI, GigaChat)<br/>
              • Настройка моделей для разных функций<br/>
              • Управление токенами и стоимостью<br/>
              • Персональные предпочтения
            </Paragraph>
          </Card>

          <Card size="small" style={{ marginBottom: '15px' }}>
            <Title level={4}>Темы оформления:</Title>
            <Paragraph>
              • Светлая и темная темы<br/>
              • Автоматическое переключение<br/>
              • Персонализация цветов<br/>
              • Адаптация под Telegram
            </Paragraph>
          </Card>

          <Card size="small">
            <Title level={4}>Личности AI:</Title>
            <Paragraph>
              • Более 6 различных личностей<br/>
              • Базовые и дополнительные режимы<br/>
              • Специализация по задачам<br/>
              • Эмоциональный анализ
            </Paragraph>
          </Card>
        </Panel>

        {/* Детальные инструкции */}
        <Panel 
          header={
            <span>
              <ThunderboltOutlined style={{ marginRight: '8px' }} />
              📖 Детальные инструкции по использованию
            </span>
          } 
          key="6"
        >
          <Card size="small" style={{ marginBottom: '15px' }}>
            <Title level={4}>🚀 Быстрый старт:</Title>
            <Paragraph>
              <strong>1. Выберите ИИ-личность:</strong><br/>
              • Перейдите в раздел "Личности"<br/>
              • Выберите подходящую личность (деловая, творческая, техническая)<br/>
              • Активируйте её нажатием на карточку<br/><br/>
              
              <strong>2. Настройте LLM провайдера:</strong><br/>
              • Откройте "Настройки ИИ"<br/>
              • Выберите между DeepSeek, OpenAI или GigaChat<br/>
              • Проверьте API ключи и лимиты<br/><br/>
              
              <strong>3. Начните общение:</strong><br/>
              • Используйте "Чат в приложении" для полного функционала<br/>
              • Или пишите прямо в Telegram боте<br/>
              • ИИ будет отвечать согласно выбранной личности
            </Paragraph>
          </Card>

          <Card size="small" style={{ marginBottom: '15px' }}>
            <Title level={4}>🎯 Продвинутые возможности:</Title>
            <Paragraph>
              <strong>📊 Аналитика и статистика:</strong><br/>
              • Раздел "Ключевые слова" — анализ тем разговоров<br/>
              • "Даты и напоминания" — управление календарем<br/>
              • Эмоциональный анализ сообщений<br/><br/>
              
              <strong>⚙️ Персонализация:</strong><br/>
              • Настройка параметров ИИ (температура, длина ответов)<br/>
              • Выбор стиля общения для каждой личности<br/>
              • Управление памятью и контекстом диалогов<br/><br/>
              
              <strong>🔒 Управление данными:</strong><br/>
              • Просмотр истории всех диалогов<br/>
              • Экспорт важных разговоров<br/>
              • Настройки приватности и безопасности
            </Paragraph>
          </Card>

          <Card size="small" style={{ marginBottom: '15px' }}>
            <Title level={4}>💡 Советы по эффективному использованию:</Title>
            <Paragraph>
              <strong>🧠 Выбор личности:</strong><br/>
              • Деловая — для рабочих задач и планирования<br/>
              • Творческая — для генерации идей и креатива<br/>
              • Техническая — для программирования и анализа<br/>
              • Эмоциональная — для поддержки и общения<br/><br/>
              
              <strong>💬 Качество диалогов:</strong><br/>
              • Формулируйте четкие и конкретные вопросы<br/>
              • Используйте контекст предыдущих сообщений<br/>
              • Экспериментируйте с разными стилями общения<br/>
              • Анализируйте ключевые слова для улучшения запросов<br/><br/>
              
              <strong>⚡ Оптимизация производительности:</strong><br/>
              • Регулярно очищайте историю через мини-приложение<br/>
              • Следите за лимитами токенов LLM<br/>
              • Используйте напоминания для важных задач<br/>
              • Настройте уведомления под свои потребности
            </Paragraph>
          </Card>
        </Panel>

        {/* Поддержка */}
        <Panel 
          header={
            <span>
              <BulbOutlined style={{ marginRight: '8px' }} />
              📞 Поддержка
            </span>
          } 
          key="7"
        >
          <Card size="small">
            <Title level={4}>Если что-то не работает:</Title>
            <Paragraph>
              • Перезапустите mini-app<br/>
              • Проверьте интернет-соединение<br/>
              • Обратитесь к разработчику через поддержку<br/>
              • Используйте команду <code>/help</code> в боте для актуальной информации
            </Paragraph>
            
            <Divider />
            
            <Title level={4}>💡 Полезные советы:</Title>
            <Paragraph>
              • Будьте осторожны с командами удаления<br/>
              • Регулярно проверяйте настройки LLM<br/>
              • Экспериментируйте с разными личностями<br/>
              • Изучайте анализ эмоций для лучшего понимания общения
            </Paragraph>
          </Card>
        </Panel>
      </Collapse>

      {/* Модальное окно с подробностями об удалении */}
      <Modal
        title={
          <span style={{ color: '#ff4d4f' }}>
            <WarningOutlined style={{ marginRight: '8px' }} />
            КРИТИЧЕСКИ ВАЖНО ОБ УДАЛЕНИИ!
          </span>
        }
        open={isDeletionModalOpen}
        onCancel={() => setIsDeletionModalOpen(false)}
        footer={[
          <Button key="close" onClick={() => setIsDeletionModalOpen(false)}>
            Понятно
          </Button>
        ]}
        width={600}
      >
        <Alert
          message="🚨 Важная информация об удалении!"
          description={
            <div>
              <p>
                <strong>❌ Удаление в Telegram боте:</strong><br/>
                Удаляет сообщения только визуально, но они остаются в базе данных!
              </p>
              <p>
                <strong>✅ Удаление в мини-приложении:</strong><br/>
                Реально удаляет сообщения из базы данных навсегда!
              </p>
            </div>
          }
          type="warning"
          style={{ marginBottom: '20px' }}
        />

        <Card title="✅ Правильный способ удаления:" size="small" style={{ marginBottom: '15px' }}>
          <ul>
            <li>Откройте мини-приложение (кнопка "Меню")</li>
            <li>Перейдите в "Чат в приложении"</li>
            <li>Используйте кнопку "🗑️ Очистить историю"</li>
            <li>Подтвердите удаление в диалоге</li>
          </ul>
        </Card>

        <Card title="❌ Что НЕ работает для реального удаления:" size="small" style={{ marginBottom: '15px' }}>
          <ul>
            <li>Удаление сообщений в Telegram боте</li>
            <li>Команды /delete_last, /clear_chat</li>
            <li>Долгий тап → Delete в Telegram</li>
            <li>Любые действия в интерфейсе Telegram</li>
          </ul>
        </Card>

        <Alert
          message="💡 Рекомендация"
          description="Для реального удаления сообщений всегда используйте мини-приложение! Только там удаление работает правильно."
          type="info"
        />
      </Modal>
    </div>
  );
};

export default Help;
